SELECT count(*) FROM hits
SELECT count(*) FROM hits WHERE AdvEngineID <> 0
SELECT sum(AdvEngineID), count(*), avg(ResolutionWidth) FROM hits
SELECT avg(UserID) FROM hits
SELECT count(*) AS u FROM (SELECT DISTINCT UserID FROM hits)
SELECT count(*) AS u FROM (SELECT DISTINCT SearchPhrase FROM hits)
SELECT min(EventDate), max(EventDate) FROM hits
SELECT AdvEngineID, count(*) AS c FROM hits WHERE AdvEngineID <> 0 GROUP BY AdvEngineID ORDER BY c DESC
SELECT RegionID, count(*) AS u FROM (SELECT DISTINCT RegionID, UserID FROM hits) GROUP BY RegionID ORDER BY u DESC LIMIT 10
SELECT RegionID, sum(s) AS s, sum(c) AS c, sum(w) / sum(c) AS w, count(*) AS u FROM (SELECT RegionID, UserID, sum(AdvEngineID) AS s, count(*) AS c, sum(ResolutionWidth) AS w FROM hits GROUP BY RegionID, UserID) GROUP BY RegionID ORDER BY c DESC LIMIT 10
SELECT MobilePhoneModel, count(*) AS u FROM (SELECT DISTINCT MobilePhoneModel, UserID FROM hits WHERE MobilePhoneModel <> '') GROUP BY MobilePhoneModel ORDER BY u DESC LIMIT 10
SELECT MobilePhone, MobilePhoneModel, count(*) AS u FROM (SELECT DISTINCT MobilePhone, MobilePhoneModel, UserID FROM hits WHERE MobilePhoneModel <> '') GROUP BY MobilePhone, MobilePhoneModel ORDER BY u DESC LIMIT 10
SELECT SearchPhrase, count(*) AS c FROM hits WHERE SearchPhrase <> '' GROUP BY SearchPhrase ORDER BY c DESC LIMIT 10
SELECT SearchPhrase, count(*) AS u FROM (SELECT DISTINCT SearchPhrase, UserID FROM hits WHERE SearchPhrase <> '') GROUP BY SearchPhrase ORDER BY u DESC LIMIT 10
SELECT SearchEngineID, SearchPhrase, count(*) AS c FROM hits WHERE SearchPhrase <> '' GROUP BY SearchEngineID, SearchPhrase ORDER BY c DESC LIMIT 10
SELECT UserID, count(*) AS c FROM hits GROUP BY UserID ORDER BY c DESC LIMIT 10
SELECT UserID, SearchPhrase, count(*) AS c FROM hits GROUP BY UserID, SearchPhrase ORDER BY c DESC LIMIT 10
SELECT * FROM (SELECT UserID, SearchPhrase, count(*) AS c FROM hits GROUP BY UserID, SearchPhrase) LIMIT 10
SELECT UserID, TIMEDIFF(EventTime, TIMETRUNCATE(EventTime, 1h, 0), 1m) AS m, SearchPhrase, count(*) AS c FROM hits GROUP BY UserID, m, SearchPhrase ORDER BY c DESC LIMIT 10
SELECT UserID FROM hits WHERE UserID = 435090932899640449
SELECT count(*) FROM hits WHERE URL LIKE '%google%'
SELECT SearchPhrase, min(URL) AS mu, count(*) AS c FROM hits WHERE URL LIKE '%google%' AND SearchPhrase <> '' GROUP BY SearchPhrase ORDER BY c DESC LIMIT 10
SELECT SearchPhrase, min(mu) AS mu, min(mt) AS mt, sum(c) AS c, count(*) AS u FROM (SELECT SearchPhrase, UserID, min(URL) AS mu, min(Title) AS mt, count(*) AS c FROM hits WHERE Title LIKE '%Google%' AND URL NOT LIKE '%.google.%' AND SearchPhrase <> '' GROUP BY SearchPhrase, UserID) GROUP BY SearchPhrase ORDER BY c DESC LIMIT 10
SELECT * FROM hits WHERE URL LIKE '%google%' ORDER BY EventTime LIMIT 10
SELECT SearchPhrase FROM hits WHERE SearchPhrase <> '' ORDER BY EventTime LIMIT 10
SELECT SearchPhrase FROM hits WHERE SearchPhrase <> '' ORDER BY SearchPhrase LIMIT 10
SELECT SearchPhrase FROM hits WHERE SearchPhrase <> '' ORDER BY EventTime, SearchPhrase LIMIT 10
SELECT CounterID, avg(length(URL)) AS l, count(*) AS c FROM hits WHERE URL <> '' GROUP BY CounterID HAVING count(*) > 100000 ORDER BY l DESC LIMIT 25
SELECT COALESCE(REGEXP_EXTRACT(Referer, '^https?://(www[.])?([^/]+)/.*$', 2), Referer) AS k, avg(length(Referer)) AS l, count(*) AS c, min(Referer) AS mr FROM hits WHERE Referer <> '' GROUP BY k HAVING count(*) > 100000 ORDER BY l DESC LIMIT 25
